+            vehicle.cur_speed = 2;
+            vehicle.cached_max_speed = 100;
+            let mut engine = vehicle.effective_engine().clone();
+            engine.visual_effect = 0x28; // Standard diesel, no NewGRF callbacks.
+            let mut state = GameState::from_map(Map::new_flat(4, 4, 0));
+            state.engine_catalog = vec![engine];
