+                state,
+                loaded_file: false,
+                ottdmap_extras: None,
+            });
+            world.insert_resource(EffectVehicleFrames {
+                steam: vec![AtlasSprite {
+                    image: Handle::default(),
+                    atlas: TextureAtlas {
+                        layout: Handle::default(),
+                        index: 0,
+                    },
+                    size: Vec2::splat(16.0),
+                }],
+                diesel: Vec::new(),
+                electric_spark: Vec::new(),
+                explosion_large: Vec::new(),
+                breakdown: Vec::new(),
+            });
+            world.insert_resource(SimHudControls {
+                sound_vehicle: false,
+                ..default()
+            });
+            world.init_resource::<ClientPreferences>();
+            world.init_resource::<SimClock>();
+            world.init_resource::<TrainSmokeSpawnClock>();
+            world.init_resource::<TrainSmokeSortSequence>();
+            world.init_resource::<Messages<PlayWorldSfx>>();
+            for &tick in rendered_ticks {
+                world.resource_mut::<SimWorld>().state.tick = GameTick::new(tick);
+                world.run_system_once(spawn_train_smoke).unwrap();
+            }
+            world.resource::<SimWorld>().state.random
+        }
+
+        let initial = GameState::from_map(Map::new_flat(4, 4, 0)).random;
+        let mut one_draw = initial;
+        let _ = one_draw.next();
+        let mut two_draws = one_draw;
+        let _ = two_draws.next();
+        let separate_frames = evaluate(&[1, 2]);
+        let catchup_frame = evaluate(&[2]);
+        assert_eq!(separate_frames, two_draws);
+        assert_eq!(catchup_frame, one_draw);
+        assert_ne!(
+            catchup_frame, separate_frames,
+            "the standalone clock change cannot preserve effect RNG yet"
+        );
+    }
