+fn sim_frame_time_budget(speed: f32) -> Duration {
+    // Bevy clamps real time before multiplying by relative speed.
+    Duration::from_secs_f64(f64::from(MAX_SIM_TICKS_PER_FRAME) / (SIM_TICK_HZ * f64::from(speed)))
