+    #[test]
+    fn wall_clock_cadence_preserves_native_ticks_with_slow_render_frames() {
+        #[derive(Resource, Default)]
+        struct DrawFrames(u32);
+
+        for (frames, delta) in [
+            (100, Duration::from_millis(10)),
+            (60, Duration::from_nanos(16_666_667)),
+            (30, Duration::from_nanos(33_333_334)),
+            (20, Duration::from_millis(50)),
+            (10, Duration::from_millis(100)),
+        ] {
+            let mut app = wall_clock_test_app(1.0);
+            app.init_resource::<DrawFrames>();
+            app.add_systems(Update, |mut count: ResMut<DrawFrames>| count.0 += 1);
+            let mut expected = app.world().resource::<SimWorld>().state.clone();
+            let initial_tick = expected.tick.get();
+            for _ in 0..37 {
+                expected.step();
+            }
+            for _ in 0..frames {
+                advance_wall_time(&mut app, delta);
+                let alpha = app.world().resource::<SimClock>().tick_alpha;
+                assert!(
