+            }
+
+            let state = &app.world().resource::<SimWorld>().state;
+            assert_eq!(state.tick.get() - initial_tick, 37, "frames={frames}");
+            assert_eq!(state.canonical_hash(), expected.canonical_hash());
+            assert_eq!(state.random, expected.random);
+            assert_eq!(app.world().resource::<DrawFrames>().0, frames);
+        }
+    }
