+            let mut app = wall_clock_test_app(speed);
+            // Keep a fractional tick before the stall, so the bound includes
+            // the fixed loop's previous remainder rather than an empty clock.
+            advance_wall_time(&mut app, Duration::from_secs_f64(0.023 / f64::from(speed)));
+            let before_tick = app.world().resource::<SimWorld>().state.tick.get();
+            let before_alpha = app.world().resource::<SimClock>().tick_alpha;
+
+            advance_app_time(&mut app, 10_000);
